const calloutBegin = {
	callback: () => {},
	text: "LOC_TUTORIAL_CALLOUT_BEGIN",
	actionKey: "inline-accept",
	closes: true,
};
const calloutClose = {
	callback: () => {},
	text: "LOC_TUTORIAL_CALLOUT_CLOSE",
	actionKey: "inline-cancel",
	closes: true,
};
const calloutContinue = {
	callback: () => {},
	text: "LOC_TUTORIAL_CALLOUT_CONTINUE",
	actionKey: "inline-accept",
	closes: true,
};

// ---------------------------------------------------------------------------
// Defines for option buttons with a 'nextID' associated
//
// @ts-ignore
function calloutAcceptNext(nextID: string): TutorialCalloutOptionDefinition {
	return TutorialSupport.calloutAcceptNext(nextID);
}
// @ts-ignore
function calloutBeginNext(nextID: string): TutorialCalloutOptionDefinition {
	return TutorialSupport.calloutBeginNext(nextID);
}
// @ts-ignore
function calloutCloseNext(nextID: string): TutorialCalloutOptionDefinition {
	return TutorialSupport.calloutCloseNext(nextID);
}
// @ts-ignore
